import ftplib
import logging
import os
import re

from taf.transport.ssh import connect

from ...utils.decorator import IgnoreErrors
from ...utils.logger import logger


class Downloader:
    @IgnoreErrors("FTP download operation failed")
    def get_files_via_ftp(self, host, username, password, src_dir, src_name, dst_dir):
        """Get files from specified host via FTP protocol.

        :param string host:      IP address of remote host.
        :param string username:  Username available on remote host.
        :param string password:  Password available on remote host.
        :param string src_dir:   Directory where files are available on remote host.
        :param string src_name:  Name or python regexp to find necessary files.
        :param string dst_dir:   Path to directory where files should be downloaded.
        """
        # TODO
        logging.warning(
            "You should not rely on downloading any BTS files via FTP!\n"
            "This is a legacy feature, will be removed in one of the next releases of taf.sw.reporting_portal."
        )

        ftp_client = self._open_ftp_connection(host, username, password, src_dir)
        self._get_files_via_ftp(ftp_client, src_name, dst_dir)
        ftp_client.close()

    @IgnoreErrors("SSH download operation failed")
    def get_files_via_ssh(self, host, username, password, src_dir, src_name, dst_dir):
        """get files from specified host via SSH/SCP protocol.

        :param string host:      IP address of remote host.
        :param string username:  Username available on remote host.
        :param string password:  Password available on remote host.
        :param string src_dir:   Directory where files are available on remote host.
        :param string src_name:  Name or python regexp to find necessary files.
        :param string dst_dir:   Path to directory where files should be downloaded.
        """
        src_path = self._create_path(src_dir, src_name)
        dst_path = self._create_path(dst_dir, None)
        ssh_connection = self._open_ssh_connection(host, username, password)
        self._get_files_via_ssh(ssh_connection, src_path, dst_path)
        ssh_connection.disconnect()

    def _create_path(self, directory, name):
        if name:
            return os.path.join(directory, name)
        else:
            return directory

    def _open_ftp_connection(self, host, username, password, src_dir):
        ftp = ftplib.FTP(host, timeout=10)
        ftp.login(username, password)
        ftp.cwd(src_dir)
        return ftp

    def _get_files_via_ftp(self, ftp_client, src_name, dst_dir):
        try:
            found_names = self._find_matching_files(ftp_client.nlst(), src_name)
            for each in found_names:
                self._get_file_via_ftp(ftp_client, each, dst_dir)
        except Exception as e:
            logger.debug(f"Error while getting files via FTP: {str(e)}")

    def _open_ssh_connection(self, host, username, password):
        ssh_connection = connect(host, username, password)
        return ssh_connection

    def _get_files_via_ssh(self, ssh_connection, src_path, dst_path):
        try:
            ssh_connection.files.get(dst_path, src_path)
        except Exception as e:
            logger.debug(f"Error while getting files via SSH: {str(e)}")

    def _find_matching_files(self, files_list, name):
        regexp = re.compile(name)
        return [each for each in files_list if regexp.search(each)]

    def _get_file_via_ftp(self, ftp, src_file, dst_dir):
        dst_path = self._create_path(dst_dir, src_file)
        ftp.retrbinary(f"RETR {src_file}", open(dst_path, "wb").write)
